<script lang="ts">
 import { untrack } from 'svelte'; import { evaluate } from './blade/evaluate'; import { DEFAULT_BLADE_CONFIG, DEFAULT_BLADE_TREE, type BladeConfig } from './blade/materials'; import type { BladeTree } from './blade/tree'; import { bladeConfigShaped } from './config'; import Viewport from './viewport/Viewport.svelte'; import type { ViewportProbe } from './viewport/camera-rig';
 let { tree=DEFAULT_BLADE_TREE, config=DEFAULT_BLADE_CONFIG, conceptName='Concept 1', readOnly=false, openCompare=false, concepts:seedConcepts=undefined, commitConceptCard=undefined, setPrediction=undefined, onFrame=undefined, onViewportReady=undefined }:{tree?:BladeTree;config?:BladeConfig;conceptName?:string;readOnly?:boolean;openCompare?:boolean;concepts?:{id:string;name:string;features:BladeTree;committed?:boolean}[];commitConceptCard?:(conceptId:string)=>Promise<unknown>;setPrediction?:(conceptId:string,rationale:string)=>Promise<unknown>;onFrame?:(ms:number)=>void;onViewportReady?:(probe:ViewportProbe)=>void}=$props();
 // The concept list is the document. `draft` is the working copy of the ACTIVE concept and
 // `accepted` is what Accept last committed to it, so Cancel has something to revert to.
 let concepts=$state<{id:string;name:string;features:BladeTree;committed:boolean}[]>(untrack(()=>
  seedConcepts?.map((c)=>({id:c.id,name:c.name,features:structuredClone(c.features),committed:c.committed??false}))
   ??[{id:'c1',name:conceptName,features:structuredClone(tree),committed:false}]
 ));
 let activeId=$state(untrack(()=>seedConcepts?.[0]?.id??'c1'));
 const active=$derived(concepts.find((c)=>c.id===activeId)??concepts[0]);
 function clone(t:BladeTree):BladeTree{return structuredClone($state.snapshot(t) as BladeTree)}
 let selected=$state('body-revolve');
 let compare=$state(untrack(()=>openCompare));
 let rationale=$state('');
 let predicted=$state('');
 // The prediction gate is PEDAGOGICAL, not a security boundary: it exists so a student
 // commits to an answer before the comparative physics is shown. Nothing behind it is
 // secret, and `revealed` is deliberately a separate flag from the rationale field --
 // keyed on the field itself, the physics unlocked on the first keystroke.
 let revealed=$state(false);
 let renaming=$state(false);
 let renameTo=$state('');
 let armedDelete=$state('');
 let accepted=$state(untrack(()=>structuredClone($state.snapshot(concepts[0].features) as BladeTree)));
 let draft=$state(untrack(()=>structuredClone($state.snapshot(concepts[0].features) as BladeTree)));
 let saved=$state('Saved');
 let history=$state<BladeTree[]>([]);
 // A config arrives from the document row on the real page, so the component
 // boundary is where an unusable one has to be caught. It is NAMED rather than
 // swapped silently: a rail quoting limits from a config nobody asked for is
 // worse than a rail saying which limits it is quoting.
 const configOk=$derived(bladeConfigShaped(config));
 const cfg=$derived(configOk?config:DEFAULT_BLADE_CONFIG);
 let viewport=$state<{zoomToFit():void;previousView():void;standardView(n:'Front'|'Back'|'Left'|'Right'|'Top'|'Bottom'|'Isometric'):void;cycleDisplayStyle():void;toggleProjection():void;currentStyle():string;currentProjection():string}|null>(null);
 let orienting=$state(false);
 const STANDARD=['Front','Back','Left','Right','Top','Bottom','Isometric'] as const;
 const result=$derived(evaluate(draft,cfg));
 const canReveal=$derived(!!predicted&&rationale.trim().length>0);
 const labels:Record<string,string>={'body-revolve':'Body Revolve','hex-extension':'Hex Extension','blade-sketch':'Blade Sketch','blade-extrude':'Blade Extrude','blade-pattern':'Circular Pattern','blade-mount':'Blade Mount'};
 function accept(){history=[...history.slice(-49),clone(accepted)];accepted=clone(draft);writeActive();saved='Unsaved'}
 function cancel(){draft=clone(accepted)}
 function writeActive(){const i=concepts.findIndex((c)=>c.id===activeId);if(i>=0)concepts[i]={...concepts[i],features:clone(draft)}}
 function load(id:string){writeActive();activeId=id;const c=concepts.find((x)=>x.id===id);if(!c)return;accepted=clone(c.features);draft=clone(c.features);armedDelete='';renaming=false}
 function nextId(){let n=concepts.length+1;while(concepts.some((c)=>c.id===`c${n}`))n++;return `c${n}`}
 function newConcept(){writeActive();const id=nextId();concepts=[...concepts,{id,name:`Concept ${concepts.length+1}`,features:clone(cfg.defaultFeatures),committed:false}];load(id)}
 function duplicate(){writeActive();const id=nextId();concepts=[...concepts,{id,name:`${active.name} copy`,features:clone(active.features),committed:false}];load(id)}
 function startRename(){renameTo=active.name;renaming=true}
 function commitRename(){const name=renameTo.trim();if(name){const i=concepts.findIndex((c)=>c.id===activeId);if(i>=0)concepts[i]={...concepts[i],name}}renaming=false}
 // The last concept is never deletable: a document with no concept has nothing to load.
 function removeConcept(){if(concepts.length<2)return;const rest=concepts.filter((c)=>c.id!==activeId);concepts=rest;armedDelete='';load(rest[0].id)}
 async function commit(){if(!commitConceptCard)return;await commitConceptCard(activeId);const i=concepts.findIndex((c)=>c.id===activeId);if(i>=0)concepts[i]={...concepts[i],committed:true}}
 async function reveal(){if(!canReveal)return;revealed=true;await setPrediction?.(predicted,rationale.trim())}
</script>
<div class="ideacad" data-testid="ideacad-editor">
 <header><div><span class="eyebrow">IDEACAD / BLADE</span><h2>{active.name}</h2></div><div class="save" aria-live="polite">{saved}</div></header>
 <div class="stage">
  <aside class="tree" aria-label="FeatureManager"><h3>FeatureManager</h3>{#each draft.features as feature}<button class:active={selected===feature.id} onclick={()=>selected=feature.id} ondblclick={()=>selected=feature.id}>{labels[feature.id]}</button>{/each}<button>Materials</button><button>Standard Parts <span>UNVERIFIED</span></button></aside>
  <section class="viewport" aria-label="3D viewport"><nav aria-label="View toolbar"><button title="Zoom to fit (F)" onclick={()=>viewport?.zoomToFit()}>Fit</button><button title="Previous view (Ctrl+Shift+Z)" onclick={()=>viewport?.previousView()}>Previous</button><button title="View orientation (Ctrl+1 to Ctrl+7)" aria-expanded={orienting} aria-controls="ideacad-orientation" onclick={()=>orienting=!orienting}>Orientation</button><button title="Display style" onclick={()=>viewport?.cycleDisplayStyle()}>Edges</button><button title="Perspective" onclick={()=>viewport?.toggleProjection()}>Perspective</button></nav>{#if orienting}<ul class="orient" id="ideacad-orientation" aria-label="Standard views">{#each STANDARD as view,i}<li><button onclick={()=>{viewport?.standardView(view);orienting=false}}>{view}<small>Ctrl+{i+1}</small></button></li>{/each}</ul>{/if}<Viewport bind:this={viewport} evaluation={result} rotation={draft.rotation} {onFrame} onReady={onViewportReady}/>{#if !readOnly}<footer><button class="accept" onclick={accept}>✓ <span>Accept</span></button><button class="cancel" onclick={cancel}>× <span>Cancel</span></button></footer>{/if}</section>
  <aside class="readouts"><h3>Rules</h3>{#each result.rules.slice(0,4) as rule}<div class="metric"><span>{rule.label}</span><strong>{rule.id==='mass'?`${rule.value.toFixed(0)} g`:`${rule.value.toFixed(2)} in`}</strong><b class:fail={!rule.pass}>{rule.pass?'PASS':'FAIL'}</b></div>{/each}<div class="metric"><span>Center of mass</span><strong>{result.comHeightIn.toFixed(2)} in</strong></div>{#if !configOk}<p class="notice">CONFIG UNREADABLE, SHOWING DEFAULT LIMITS</p>{/if}{#if result.unverifiedStandardParts}<p class="notice">UNVERIFIED STANDARD PARTS</p>{/if}</aside>
 </div>
 <section class="concepts" aria-label="Concepts">{#each concepts as concept (concept.id)}<button class="card" class:active={concept.id===activeId} onclick={()=>load(concept.id)}>{concept.name}<small>{concept.id===activeId?'ACTIVE':concept.committed?'COMMITTED':'\u00a0'}</small></button>{/each}{#if !readOnly}{#if renaming}<input class="rename" bind:value={renameTo} placeholder="Concept name" aria-label="Concept name"/><button onclick={commitRename}>Save name</button><button onclick={()=>renaming=false}>Cancel rename</button>{:else}<button onclick={newConcept}>New</button><button onclick={duplicate}>Duplicate</button><button onclick={startRename}>Rename</button>{#if concepts.length>1}{#if armedDelete===activeId}<button class="danger" onclick={removeConcept}>Delete {active.name}</button><button onclick={()=>armedDelete=''}>Keep it</button>{:else}<button onclick={()=>armedDelete=activeId}>Delete</button>{/if}{:else}<span class="note">Your last concept cannot be deleted.</span>{/if}<button onclick={()=>compare=!compare}>Compare</button>{#if commitConceptCard}<button onclick={commit}>Commit as concept card</button>{/if}{/if}{/if}</section>
 {#if compare}<section class="compare" aria-label="Compare concepts"><h3>Compare concepts</h3>{#if !revealed}<p>Which of your concepts spins longest? Pick one and say why.</p><select value={predicted} onchange={(e)=>predicted=e.currentTarget.value} aria-label="Pick a concept"><option value="">Pick a concept</option>{#each concepts as concept (concept.id)}<option value={concept.id}>{concept.name}</option>{/each}</select><input bind:value={rationale} placeholder="Say why" aria-label="Say why"/><button aria-disabled={!canReveal} onclick={reveal}>Reveal physics</button>{#if !canReveal}<p class="note">Pick a concept and say why before the physics is revealed.</p>{/if}{:else}<p>Prediction: {concepts.find((c)=>c.id===predicted)?.name ?? predicted}. {rationale}</p><dl><dt>I</dt><dd>{result.inertiaGcm2.toFixed(1)} g·cm²</dd><dt>k</dt><dd>{result.radiusOfGyrationCm.toFixed(2)} cm</dd></dl>{/if}<button class="close" onclick={()=>compare=false}>Close</button></section>{/if}
</div>
<style>
 :global(body){margin:0}.ideacad{--tree-width:300px;--rail-width:280px;position:relative;height:min(760px,calc(100vh - 2rem));display:grid;grid-template-rows:auto minmax(0,1fr) auto;background:var(--surface-0);color:var(--text-1);font-family:Rajdhani,sans-serif;border:1px solid var(--boundary)}header{display:flex;justify-content:space-between;align-items:center;padding:.75rem 1rem;border-bottom:1px solid var(--boundary)}h2,h3{font-family:'Chakra Petch',sans-serif;margin:.15rem 0}h2::before{content:none}.eyebrow,.save,.metric span,.notice{font:12px 'Share Tech Mono',monospace;letter-spacing:.08em}.stage{display:grid;grid-template-columns:var(--tree-width) minmax(0,1fr) var(--rail-width);min-width:0;min-height:0}aside{overflow:auto;background:var(--surface-1);padding:1rem}.tree{border-right:1px solid var(--boundary)}button,input,select{min-height:44px;min-width:44px;color:var(--text-1);background:var(--surface-2);border:1px solid var(--boundary);border-radius:var(--radius-control);font:inherit}.tree button{display:block;width:100%;text-align:left;padding:.5rem;margin:.25rem 0}.tree button.active{border-color:var(--green);background:var(--green-tint)}button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid var(--focus-ring);outline-offset:2px}.tree span,.notice{color:var(--copper)}.viewport{position:relative;overflow:hidden;min-height:360px;background:var(--surface-0)}.viewport nav{position:absolute;top:.75rem;left:.75rem;right:.75rem;z-index:2;display:flex;flex-wrap:wrap;justify-content:center;gap:.25rem}.viewport nav button{padding:0 .7rem;flex:0 0 auto}.orient{position:absolute;top:4rem;left:50%;transform:translateX(-50%);z-index:4;margin:0;padding:.4rem;list-style:none;display:grid;gap:.25rem;background:var(--surface-1);border:1px solid var(--boundary);box-shadow:var(--bevel-raised);max-height:calc(100% - 5rem);overflow:auto}.orient button{display:flex;justify-content:space-between;gap:1rem;width:100%;padding:0 .7rem;text-align:left}.orient small{color:var(--text-2);font:12px 'Share Tech Mono',monospace;align-self:center}.readouts{border-left:1px solid var(--boundary)}.metric{display:grid;grid-template-columns:1fr auto;gap:.35rem;padding:.7rem 0;border-bottom:1px solid var(--hairline)}.metric b{grid-column:1/-1;color:var(--green);font-family:'Share Tech Mono'}.metric b.fail{color:var(--crimson)}.concepts{display:flex;gap:.5rem;overflow:auto;padding:.75rem;border-top:1px solid var(--boundary);scroll-snap-type:x mandatory}.concepts button{flex:0 0 auto;padding:0 1rem;scroll-snap-align:start}.concepts .card{min-width:180px}.concepts small{display:block;color:var(--green)}footer{position:absolute;right:1rem;bottom:1rem;display:flex;gap:.5rem;z-index:2}footer button{padding:0 .9rem}.accept{border-color:var(--green)}.cancel{border-color:var(--crimson)}.compare::before{content:"";position:fixed;inset:0;background:rgb(0 0 0/.45);z-index:-1}.compare{position:absolute;inset:5rem 10% auto;max-height:calc(100% - 10rem);overflow:auto;z-index:3;padding:1.5rem;background:var(--surface-1);border:1px solid var(--boundary);box-shadow:var(--bevel-raised)}.compare input,.compare select,.compare button{margin:.3rem;padding:0 .7rem}.compare button[aria-disabled='true']{color:var(--text-2);border-color:var(--hairline)}.note{font:12px 'Share Tech Mono',monospace;color:var(--text-2)}.concepts .note{align-self:center;padding:0 .5rem}.concepts .danger{border-color:var(--crimson)}.concepts .rename{flex:0 0 auto;padding:0 .7rem;min-width:180px}
 @media(max-width:1023px){.ideacad{height:auto;min-height:100vh}.ideacad aside{overflow:visible}.ideacad footer{position:static;padding:.75rem 1rem}.ideacad .stage{display:flex;flex-direction:column}.viewport{order:0;min-height:360px}.readouts{order:1;border-left:0;border-top:1px solid var(--boundary)}.tree{order:2;border-right:0;border-top:1px solid var(--boundary)}.compare{position:fixed;inset:auto 0 0}.viewport nav{max-width:100%;overflow:auto}}
</style>
